import pandas as pd

def _rank(x):
    return x.rank(axis=1, pct=True)


def _delta(x, d):
    return x - x.shift(d)


def _corr(x, y, d):
    return x.rolling(d).corr(y).replace([np.inf, -np.inf], np.nan)


def _ts_rank(x, d):
    def f(a):
        return (a <= a[-1]).sum() / float(len(a))
    return x.rolling(d).apply(f, raw=True)


